const mockGetProjectRepos = vi.fn();

// ---------------------------------------------------------------------------
// Import under test
// ---------------------------------------------------------------------------

import { handleTaskMove } from '../../src/main/ipc/handlers/task-move';
import { legacyAutoBranchNameFor } from '../../src/main/git/task-worktree-folder';
import { isAutoGeneratedBranch } from '../../src/main/git/git-checks';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const TASK_ID = 'task-branchguard-0001';
const SOURCE_LANE_ID = 'lane-todo';
const TARGET_LANE_ID = 'lane-doing';
const TASK_TITLE = 'Rework notifications';
/** The exact branch #538 carried, and the shape of any agent-supplied name. */
const CUSTOM_BRANCH = 'rework-notifications-desktop-push';

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    display_id: 1,
    title: TASK_TITLE,
    description: '',
    swimlane_id: SOURCE_LANE_ID,
    position: 0,
    agent: null,
    session_id: null,
    worktree_path: null,
    branch_name: null,
    pr_number: null,
    pr_url: null,
    base_branch: null,
    use_worktree: null,
    labels: [],
    priority: 0,
    attachment_count: 0,
    archived_at: null,
    created_at: '2025-01-01T00:00:00.000Z',
    updated_at: '2025-01-01T00:00:00.000Z',
    ...overrides,
  };
}

function makeSwimlane(id: string, overrides: Partial<Swimlane> = {}): Swimlane {
  return {
    id,
    name: `Lane ${id}`,
    role: null,
    position: 0,
    color: '#888',
    icon: null,
    is_archived: false,
    is_ghost: false,
    permission_mode: null,
    auto_spawn: true,
    auto_command: null,
    plan_exit_target_id: null,
    agent_override: null,
    model_override: null,
    effort_override: null,
    handoff_context: false,
    created_at: '2025-01-01T00:00:00.000Z',
    ...overrides,
  };
}

function makeContext() {
  return {
    currentProjectId: 'proj-branchguard',
    currentProjectPath: '/mock/branchguard-project',
    boardEvents: { emitBoardChanged: vi.fn() },
    mainWindow: {
      isDestroyed: vi.fn(() => false),
      webContents: { send: vi.fn() },
    },
    sessionManager: {
      removeByTaskId: vi.fn(),
      killByTaskId: vi.fn(),
      listSessions: vi.fn(() => []),
      suspend: vi.fn(async () => {}),
    },
    configManager: {
      getEffectiveConfig: vi.fn(() => ({ git: { defaultBaseBranch: 'main' } })),
    },
    boardConfigManager: { getDefaultBaseBranch: vi.fn(() => null) },
    terminalSubmitScheduler: { cancel: vi.fn(), scheduleKeystrokes: vi.fn() },
    projectRepo: { getById: vi.fn(() => ({ id: 'proj-branchguard', default_agent: 'claude' })) },
  };
}

/**
 * Drive a move whose worktree creation fails, so the stale-resource cleanup
 * runs. The move rejects by design (`Worktree setup failed: ...`), which is what
 * the renderer turns into its toast.
 */
async function runFailingMove(task: Task): Promise<void> {
  const sourceLane = makeSwimlane(SOURCE_LANE_ID, { role: 'todo' });
  const targetLane = makeSwimlane(TARGET_LANE_ID, { role: null, auto_spawn: true });

  mockGetProjectRepos.mockReturnValue({
    tasks: {
      getById: vi.fn(() => ({ ...task })),
      move: vi.fn(),
      update: vi.fn(),
      list: vi.fn(() => [{ ...task }]),
      archive: vi.fn(),
    },
    swimlanes: {
      getById: vi.fn((id: string) => {
        if (id === SOURCE_LANE_ID) return sourceLane;
        if (id === TARGET_LANE_ID) return targetLane;
        return null;
      }),
      list: vi.fn(() => [sourceLane, targetLane]),
    },
    actions: { getTransitionsFor: vi.fn(() => []) },
    attachments: { deleteByTaskId: vi.fn() },
  });

  mockEnsureTaskWorktree.mockRejectedValue(new Error("fatal: 'branch' is already used by worktree at '/repo'"));

  await expect(
    handleTaskMove(makeContext() as never, {
      taskId: task.id,
      targetSwimlaneId: TARGET_LANE_ID,
      targetPosition: 0,
    }, 'renderer'),
  ).rejects.toThrow(/Worktree setup failed/);
}

beforeEach(() => {
  vi.clearAllMocks();
  mockWithLock.mockImplementation(async (fn: () => Promise<unknown>) => fn());
  mockRemoveWorktree.mockResolvedValue(true);
  mockPruneWorktrees.mockResolvedValue(undefined);
  mockRemoveBranch.mockResolvedValue(undefined);
  mockEnsureTaskBranchCheckout.mockResolvedValue(undefined);
  mockSpawnAgent.mockResolvedValue(undefined);
});

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('handleTaskMove stale-resource cleanup: branch deletion', () => {
  it('does NOT delete a custom, agent-supplied branch when worktree creation fails', async () => {
    // Sanity-check the fixture against the real predicate, so this test cannot
    // silently pass because the branch name happened to look auto-generated.
    expect(isAutoGeneratedBranch(CUSTOM_BRANCH, TASK_ID, TASK_TITLE)).toBe(false);

    await runFailingMove(makeTask({ branch_name: CUSTOM_BRANCH }));

    // The data-loss guard. Pre-fix this was `git branch -D
    // rework-notifications-desktop-push` with the error swallowed, destroying
    // commit 4261ff1e on an unpushed branch.
    expect(mockRemoveBranch).not.toHaveBeenCalled();
    // The rest of the cleanup must still have run - the guard is scoped to the
    // branch deletion, not the whole block.
    expect(mockPruneWorktrees).toHaveBeenCalledTimes(1);
  });

  it('still deletes an auto-generated branch, so stale leftovers are cleaned', async () => {
    const task = makeTask();
    const autoBranch = legacyAutoBranchNameFor(task);
    expect(isAutoGeneratedBranch(autoBranch, TASK_ID, TASK_TITLE)).toBe(true);

    await runFailingMove(makeTask({ branch_name: autoBranch }));

    // The other direction: an over-correcting fix would strand stale branches.
    expect(mockRemoveBranch).toHaveBeenCalledWith(autoBranch);
  });

  it('still deletes the derived legacy name when the task has no branch_name at all', async () => {
    const task = makeTask({ branch_name: null });

    await runFailingMove(task);

    // The null case falls back to `legacyAutoBranchNameFor`, which is
    // auto-generated by construction, so it stays deletable.
    expect(mockRemoveBranch).toHaveBeenCalledWith(legacyAutoBranchNameFor(task));
  });
});
